--
-- Table structure for table `affiliate_admin_charges`
--

DROP TABLE IF EXISTS `affiliate_admin_charges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `affiliate_admin_charges` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador interno autoincremental',
  `uuid` char(36) NOT NULL COMMENT 'UUID v4 único del cargo administrativo',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID de la empresa asociada (tenant)',
  `payment_reference` varchar(50) NOT NULL COMMENT 'Referencia o número consecutivo de cobro',
  `vehicle_uuid` char(36) NOT NULL COMMENT 'UUID del vehículo asociado al afiliado',
  `charge_type` enum('CUOTA_ADMINISTRACION','PAGO_MENSUALIDAD','PAGO_CUPO') NOT NULL COMMENT 'Tipo de cargo administrativo aplicado',
  `payment_method` enum('EFECTIVO','TRANSFERENCIA','CHEQUE','TARJETA','CORTESIA','OTRO') NOT NULL DEFAULT 'EFECTIVO' COMMENT 'Método de pago utilizado',
  `concept` varchar(255) NOT NULL COMMENT 'Concepto o descripción corta del cobro',
  `amount` decimal(15,2) NOT NULL COMMENT 'Monto total del cargo administrativo',
  `currency_code` char(3) NOT NULL DEFAULT 'COP' COMMENT 'Código ISO de la moneda (predeterminado COP)',
  `period_date` date NOT NULL COMMENT 'Fecha correspondiente al periodo facturado',
  `due_date` date NOT NULL COMMENT 'Fecha límite de pago oportuno',
  `next_payment_date` date NOT NULL COMMENT 'Fecha programada para el siguiente pago',
  `late_fee_percentage` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'Porcentaje de recargo por mora aplicado',
  `status` enum('PENDIENTE','PAGADO','VENCIDO','EN_MORA','ANULADO') NOT NULL DEFAULT 'PENDIENTE' COMMENT 'Estado del recaudo o cartera del cargo',
  `payment_date` date DEFAULT NULL COMMENT 'Fecha en la que el afiliado realizó el pago',
  `bank_reference` varchar(100) DEFAULT NULL COMMENT 'Referencia de la transacción bancaria o pasarela',
  `notes` text DEFAULT NULL COMMENT 'Observaciones o notas adicionales sobre el cargo',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `affiliate_admin_charges_uuid_unique` (`uuid`),
  KEY `affiliate_admin_charges_company_uuid_index` (`company_uuid`),
  KEY `affiliate_admin_charges_vehicle_uuid_index` (`vehicle_uuid`),
  CONSTRAINT `affiliate_admin_charges_company_uuid_foreign` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `affiliate_admin_charges_vehicle_uuid_foreign` FOREIGN KEY (`vehicle_uuid`) REFERENCES `vehicles` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

