  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador único de la empresa',
  `uuid` char(36) NOT NULL COMMENT 'UUID universal único de la empresa',
  `person_type` enum('PERSONA NATURAL','PERSONA JURIDICA') NOT NULL COMMENT 'Tipo de persona jurídica o natural',
  `type_of_company` enum('PUBLICO','PRIVADO') NOT NULL COMMENT 'Naturaleza de la compañía',
  `economic_sector` varchar(255) DEFAULT NULL COMMENT 'Sector económico de operación',
  `legal_structure` enum('SOCIEDAD POR ACCIONES SIMPLIFICADA - SAS','SOCIEDAD DE RESPONSABILIDAD LIMITADA - LTDA','SOCIEDAD POR ACCIONES - SPA','SOCIEDAD ANONIMA - SA','UNIÓN TEMPORAL - UT','ENTIDAD SIN ÁNIMO DE LUCRO - ESAL') DEFAULT NULL COMMENT 'Estructura legal registrada',
  `document_type_uuid` char(36) NOT NULL COMMENT 'UUID del tipo de documento de la empresa',
  `document_number` varchar(20) NOT NULL COMMENT 'Número de documento único',
  `verification_digit` varchar(1) DEFAULT NULL COMMENT 'Dígito de verificación del NIT',
  `business_name` varchar(200) NOT NULL COMMENT 'Razón social legal completa',
  `trade_name` varchar(100) DEFAULT NULL COMMENT 'Nombre comercial o marca',
  `commercial_registration` varchar(50) DEFAULT NULL COMMENT 'Matrícula mercantil en Cámara de Comercio',
  `municipality_uuid` char(36) NOT NULL COMMENT 'UUID del municipio de domicilio',
  `address` varchar(200) NOT NULL COMMENT 'Dirección física completa',
  `postal_code` varchar(10) DEFAULT NULL COMMENT 'Código postal de la dirección',
  `phone` varchar(20) DEFAULT NULL COMMENT 'Teléfono corporativo principal',
  `email` varchar(100) NOT NULL COMMENT 'Correo electrónico corporativo',
  `tax_regime_uuid` char(36) NOT NULL COMMENT 'UUID del régimen fiscal asignado',
  `currency_code` char(3) DEFAULT 'COP' COMMENT 'Código ISO 4217 de moneda principal',
  `approximate_number_of_employees` char(10) DEFAULT NULL COMMENT 'Rango o número aproximado de empleados',
  `web_page` varchar(255) NOT NULL COMMENT 'Sitio web oficial',
  `country_code` char(2) DEFAULT 'CO' COMMENT 'Código ISO 3166-1 alfa-2 del país',
  `legal_representative_name` varchar(255) NOT NULL COMMENT 'Nombre(s) del representante legal',
  `legal_representative_last_name` varchar(255) NOT NULL COMMENT 'Apellido(s) del representante legal',
  `legal_representative_document_type` varchar(20) NOT NULL COMMENT 'Tipo de documento del representante legal',
  `legal_representative_document_number` varchar(20) NOT NULL COMMENT 'Número de documento del representante legal',
  `legal_representative_nationality` varchar(20) DEFAULT NULL COMMENT 'Nacionalidad del representante legal',
  `legal_representative_document_issue_date` date DEFAULT NULL COMMENT 'Fecha de expedición del documento',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Estado de habilitación de la empresa (1=activo, 0=inactivo)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `companies_uuid_unique` (`uuid`),
  KEY `companies_document_type_uuid_foreign` (`document_type_uuid`),
  KEY `companies_tax_regime_uuid_foreign` (`tax_regime_uuid`),
  KEY `companies_municipality_uuid_foreign` (`municipality_uuid`),
  CONSTRAINT `companies_document_type_uuid_foreign` FOREIGN KEY (`document_type_uuid`) REFERENCES `type_of_documents` (`uuid`) ON UPDATE CASCADE,
  CONSTRAINT `companies_municipality_uuid_foreign` FOREIGN KEY (`municipality_uuid`) REFERENCES `cities` (`uuid`) ON UPDATE CASCADE,
  CONSTRAINT `companies_tax_regime_uuid_foreign` FOREIGN KEY (`tax_regime_uuid`) REFERENCES `tax_regimes` (`uuid`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

