--
-- Table structure for table `contacts`
--

DROP TABLE IF EXISTS `contacts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `contacts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador único del contacto',
  `uuid` char(36) NOT NULL COMMENT 'UUID universal único del contacto',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID de la empresa a la que pertenece el contacto',
  `first_name` varchar(100) DEFAULT NULL COMMENT 'Nombres del contacto',
  `last_name` varchar(100) DEFAULT NULL COMMENT 'Apellidos del contacto',
  `representative_type` enum('COMERCIAL','REPRESENTANTE_LEGAL','TECNICO','CARTERA','COMPRAS','CONTACTO_FACTURACION','CUMPLIMIENTO','FINANCIERO','HSE','JURIDICO','REPRESENTANTE_LEGAL_SUPLENTE') NOT NULL COMMENT 'Cargo o función del contacto en la organización',
  `country` varchar(100) DEFAULT NULL COMMENT 'País de residencia o ubicación',
  `municipality_uuid` char(36) DEFAULT NULL COMMENT 'UUID del municipio de ubicación',
  `email` varchar(150) DEFAULT NULL COMMENT 'Correo electrónico de contacto',
  `phone_number` varchar(50) DEFAULT NULL COMMENT 'Número de teléfono de contacto',
  `remarks` text DEFAULT NULL COMMENT 'Observaciones o notas adicionales sobre el contacto',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `contacts_uuid_unique` (`uuid`),
  KEY `contacts_company_uuid_foreign` (`company_uuid`),
  KEY `contacts_municipality_uuid_foreign` (`municipality_uuid`),
  CONSTRAINT `contacts_company_uuid_foreign` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `contacts_municipality_uuid_foreign` FOREIGN KEY (`municipality_uuid`) REFERENCES `cities` (`uuid`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

