DROP TABLE IF EXISTS `contextual_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `contextual_questions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL COMMENT 'UUID ÚNICO DE LA PREGUNTA CONTEXTUAL',
  `module` varchar(100) NOT NULL COMMENT 'MÓDULO: fleet, third_parties, contract_extract, administration, general',
  `title` varchar(255) NOT NULL COMMENT 'TÍTULO DESCRIPTIVO',
  `question_text` text NOT NULL COMMENT 'TEXTO DE PREGUNTA VISIBLE EN UI',
  `patterns` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'PATRONES DE BÚSQUEDA: ["cuantos vehiculos", "total vehiculos"]' CHECK (json_valid(`patterns`)),
  `response_type` varchar(50) NOT NULL COMMENT 'TIPO: count, list, expiring, text',
  `response_template` text NOT NULL COMMENT 'TEMPLATE CON {count} {results} {entity}',
  `entity_type` varchar(100) DEFAULT NULL COMMENT 'ENTIDAD: vehicles, third_parties, fuecs...',
  `filters` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'FILTROS: {"is_active": true}' CHECK (json_valid(`filters`)),
  `expiring_days` int(11) DEFAULT NULL COMMENT 'DÍAS PARA VENCIMIENTO',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT 'ORDEN DE PRIORIDAD',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=ACTIVO, 0=INACTIVO',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `contextual_questions_uuid_unique` (`uuid`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Preguntas contextuales para el asistente virtual';
/*!40101 SET character_set_client = @saved_cs_client */;

