--
-- Table structure for table `dian_parameters`
--

DROP TABLE IF EXISTS `dian_parameters`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dian_parameters` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL COMMENT 'UUID V4 ÚNICO PARA LOS PARÁMETROS',
  `year` smallint(6) NOT NULL COMMENT 'AÑO FISCAL AL QUE APLICAN LOS PARÁMETROS',
  `uvt` decimal(10,2) NOT NULL COMMENT 'VALOR DE LA UNIDAD DE VALOR TRIBUTARIO (UVT) PARA EL AÑO',
  `iva_withholding_rate` decimal(6,4) NOT NULL DEFAULT 0.1500 COMMENT 'PORCENTAJE ESTÁNDAR DE RETENCIÓN DE IVA (EJ: 0.15 = 15%)',
  `minimum_wage` decimal(12,2) DEFAULT NULL COMMENT 'SALARIO MÍNIMO LEGAL VIGENTE MENSUAL PARA EL AÑO',
  `transport_subsidy` decimal(12,2) DEFAULT NULL COMMENT 'AUXILIO DE TRANSPORTE MENSUAL PARA EL AÑO',
  `usury_rate` decimal(6,4) DEFAULT NULL COMMENT 'TASA MÁXIMA DE USURA CERTIFICADA POR LA SUPERFINANCIERA',
  `observations` text DEFAULT NULL COMMENT 'OBSERVACIONES O NOTAS LEGALES APLICABLES AL AÑO',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dian_parameters_uuid_unique` (`uuid`),
  UNIQUE KEY `dian_parameters_year_unique` (`year`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Parámetros tributarios y económicos anuales de referencia DIAN';
/*!40101 SET character_set_client = @saved_cs_client */;

