--
-- Table structure for table `driver_licenses`
--

DROP TABLE IF EXISTS `driver_licenses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `driver_licenses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL COMMENT 'UUID de la licencia',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID de la empresa',
  `third_party_uuid` char(36) NOT NULL COMMENT 'UUID del tercero',
  `number` varchar(50) NOT NULL COMMENT 'Numero de la licencia',
  `category` enum('C1','C2','C3') NOT NULL COMMENT 'Categoria de la licencia',
  `issue_date` date NOT NULL COMMENT 'Fecha de expedicion de la licencia',
  `expiration_date` date NOT NULL COMMENT 'Fecha de expiracion de la licencia',
  `restrictions` varchar(255) DEFAULT NULL,
  `status` varchar(255) DEFAULT 'ACTIVA',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `driver_licenses_uuid_unique` (`uuid`),
  KEY `driver_licenses_third_party_uuid_foreign` (`third_party_uuid`),
  KEY `driver_licenses_company_uuid_foreign` (`company_uuid`),
  CONSTRAINT `driver_licenses_company_uuid_foreign` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `driver_licenses_third_party_uuid_foreign` FOREIGN KEY (`third_party_uuid`) REFERENCES `third_parties` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

