DROP TABLE IF EXISTS `driver_location_alerts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `driver_location_alerts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID único de la alerta',
  `uuid` char(36) NOT NULL COMMENT 'UUID único universal de la alerta',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID único universal de la empresa',
  `third_party_uuid` char(36) NOT NULL COMMENT 'UUID único universal del conductor',
  `driver_location_uuid` char(36) DEFAULT NULL COMMENT 'UUID de la ubicación que generó la alerta',
  `alert_type` enum('geofence_enter','geofence_exit','overspeed','idle','panic') NOT NULL COMMENT 'Tipo de alerta',
  `geofence_uuid` char(36) DEFAULT NULL COMMENT 'UUID de la geocerca relacionada',
  `message` text NOT NULL COMMENT 'Mensaje descriptivo de la alerta',
  `latitude` decimal(10,8) NOT NULL COMMENT 'Latitud donde ocurrió',
  `longitude` decimal(11,8) NOT NULL COMMENT 'Longitud donde ocurrió',
  `is_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Indica si la alerta fue leída',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `driver_location_alerts_uuid_unique` (`uuid`),
  KEY `idx_dla_company_read` (`company_uuid`,`is_read`),
  KEY `idx_dla_driver` (`third_party_uuid`),
  KEY `idx_dla_created_at` (`created_at`),
  KEY `driver_location_alerts_driver_location_uuid_foreign` (`driver_location_uuid`),
  KEY `idx_dla_company_read_created` (`company_uuid`,`is_read`,`created_at`),
  KEY `idx_dla_company_created` (`company_uuid`,`created_at`),
  CONSTRAINT `driver_location_alerts_company_uuid_foreign` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `driver_location_alerts_driver_location_uuid_foreign` FOREIGN KEY (`driver_location_uuid`) REFERENCES `driver_locations` (`uuid`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `driver_location_alerts_third_party_uuid_foreign` FOREIGN KEY (`third_party_uuid`) REFERENCES `third_parties` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
