DROP TABLE IF EXISTS `driver_locations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `driver_locations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID único del registro de ubicación',
  `uuid` char(36) NOT NULL COMMENT 'UUID único universal del registro',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID único universal de la empresa',
  `third_party_uuid` char(36) NOT NULL COMMENT 'UUID único universal del conductor',
  `vehicle_uuid` char(36) DEFAULT NULL COMMENT 'UUID único universal del vehículo',
  `project_uuid` char(36) DEFAULT NULL COMMENT 'UUID único universal del proyecto',
  `latitude` decimal(10,8) NOT NULL COMMENT 'Latitud del punto',
  `longitude` decimal(11,8) NOT NULL COMMENT 'Longitud del punto',
  `altitude` decimal(10,2) DEFAULT NULL COMMENT 'Altitud en metros',
  `speed` decimal(6,2) NOT NULL DEFAULT 0.00 COMMENT 'Velocidad en km/h',
  `heading` decimal(5,2) DEFAULT NULL COMMENT 'Dirección del movimiento en grados',
  `accuracy` decimal(8,2) DEFAULT NULL COMMENT 'Precisión en metros',
  `battery_level` tinyint(3) unsigned DEFAULT NULL COMMENT 'Nivel de batería (0-100)',
  `is_moving` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Indica si el dispositivo está en movimiento',
  `source` enum('gps','network','fused') NOT NULL DEFAULT 'gps' COMMENT 'Fuente de la ubicación',
  `distance_meters` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'Distancia en metros desde el punto anterior del mismo conductor',
  `recorded_at` timestamp NOT NULL DEFAULT current_timestamp() COMMENT 'Fecha y hora del registro GPS',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `driver_locations_uuid_unique` (`uuid`),
  KEY `idx_dl_driver_recorded` (`third_party_uuid`,`recorded_at`),
  KEY `idx_dl_vehicle` (`vehicle_uuid`),
  KEY `idx_dl_recorded_at` (`recorded_at`),
  KEY `idx_dl_driver_company_recorded` (`third_party_uuid`,`company_uuid`,`recorded_at`,`speed`,`distance_meters`),
  KEY `idx_dl_company_recorded` (`company_uuid`,`recorded_at`,`third_party_uuid`),
  KEY `idx_dl_company_vehicle_recorded` (`company_uuid`,`vehicle_uuid`,`recorded_at`),
  KEY `idx_dl_company_project_recorded` (`company_uuid`,`project_uuid`,`recorded_at`),
  CONSTRAINT `driver_locations_company_uuid_foreign` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `driver_locations_third_party_uuid_foreign` FOREIGN KEY (`third_party_uuid`) REFERENCES `third_parties` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `driver_locations_vehicle_uuid_foreign` FOREIGN KEY (`vehicle_uuid`) REFERENCES `vehicles` (`uuid`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
