/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inspection_results` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `inspection_uuid` char(36) NOT NULL,
  `item_uuid` char(36) NOT NULL,
  `is_selected` tinyint(1) NOT NULL DEFAULT 1,
  `status` enum('APROBADO','NO_APROBADO','NO_APLICA') NOT NULL DEFAULT 'APROBADO',
  `observations` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `inspection_results_inspection_uuid_foreign` (`inspection_uuid`),
  KEY `inspection_results_item_uuid_foreign` (`item_uuid`),
  CONSTRAINT `inspection_results_inspection_uuid_foreign` FOREIGN KEY (`inspection_uuid`) REFERENCES `vehicle_inspections` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `inspection_results_item_uuid_foreign` FOREIGN KEY (`item_uuid`) REFERENCES `inspection_items` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
