--
-- Table structure for table `occupational_safety_records`
--

DROP TABLE IF EXISTS `occupational_safety_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `occupational_safety_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador único del registro',
  `uuid` char(36) NOT NULL COMMENT 'UUID universal único',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID de la empresa propietaria del registro',
  `operation_year` int(11) NOT NULL COMMENT 'Año de operación o reporte',
  `fatalities` int(11) DEFAULT 0 COMMENT 'Número de fatalidades reportadas',
  `incapacitating_accidents_count` int(11) DEFAULT 0 COMMENT 'Número de accidentes incapacitantes',
  `total_incidents_count` int(11) DEFAULT 0 COMMENT 'Número total de incidentes',
  `lost_days_count` int(11) DEFAULT 0 COMMENT 'Total de días de incapacidad',
  `average_workers_count` int(11) DEFAULT 0 COMMENT 'Número promedio de trabajadores',
  `hours_worked` decimal(18,2) DEFAULT NULL COMMENT 'Total de horas-hombre trabajadas',
  `arl_accident_certificate_date` date DEFAULT NULL COMMENT 'Fecha de expedición certificado de accidentalidad ARL',
  `risk_level` varchar(50) DEFAULT NULL COMMENT 'Nivel de riesgo asignado',
  `arl_affiliation_certificate_date` date DEFAULT NULL COMMENT 'Fecha expedición certificado de afiliación ARL',
  `sgsst_rating` varchar(50) DEFAULT NULL COMMENT 'Calificación del SG-SST',
  `sgsst_evaluation_date` date DEFAULT NULL COMMENT 'Fecha de evaluación del SG-SST',
  `sgsst_certificate_path` varchar(255) DEFAULT NULL COMMENT 'Ruta del archivo certificado de resultado SG-SST',
  `remarks` text DEFAULT NULL COMMENT 'Observaciones generales',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `occupational_safety_records_uuid_unique` (`uuid`),
  KEY `occupational_safety_records_company_uuid_foreign` (`company_uuid`),
