--
-- Table structure for table `procedures`
--

DROP TABLE IF EXISTS `procedures`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `procedures` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `parent_procedure_uuid` char(36) DEFAULT NULL,
  `link_type` enum('CAMBIO_DE_EMPRESA','NUEVO_VEHICULO','RENOVACION','DESVINCULACION_MUTUO','DESVINCULACION_UNILATERAL') DEFAULT NULL,
  `company_uuid` char(36) DEFAULT NULL,
  `third_party_uuid` char(36) DEFAULT NULL,
  `vehicle_uuid` char(36) DEFAULT NULL,
  `procedure_code` varchar(50) NOT NULL,
  `filed_number` varchar(50) DEFAULT NULL,
  `procedure_type` enum('CARTA_DE_ACEPTACION','CAPACIDAD_TRANSPORTADORA','INCLUSION_DE_POLIZAS','TARJETA_DE_OPERACION','DESVINCULACION','RENOVACION_TARJETA','DESVINCULACION_MUTUO','DESVINCULACION_UNILATERAL') DEFAULT NULL,
  `current_step` varchar(50) DEFAULT NULL,
  `date_of_creation` date NOT NULL,
  `city_uuid` char(36) NOT NULL,
  `subject` varchar(255) DEFAULT NULL,
  `territorial_director_uuid` char(36) NOT NULL,
  `status` enum('RECIBIDO','EN_PROCESO','COMPLETADO','CANCELADO') NOT NULL DEFAULT 'RECIBIDO',
  `global_status` varchar(50) DEFAULT NULL,
  `simit_clear` tinyint(1) DEFAULT NULL COMMENT 'Sin comparendos SIMIT o con acuerdo de pago',
  `soat_valid` tinyint(1) DEFAULT NULL,
  `rtm_valid` tinyint(1) DEFAULT NULL,
  `old_card_number` varchar(20) DEFAULT NULL,
  `radicado_number` varchar(50) DEFAULT NULL,
  `payment_status` varchar(30) DEFAULT 'PENDIENTE',
  `resolution_number` varchar(50) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `procedures_uuid_unique` (`uuid`),
  KEY `procedures_city_uuid_foreign` (`city_uuid`),
  KEY `procedures_territorial_director_uuid_foreign` (`territorial_director_uuid`),
  KEY `procedures_company_uuid_foreign` (`company_uuid`),
  KEY `procedures_third_party_uuid_foreign` (`third_party_uuid`),
  KEY `procedures_vehicle_uuid_foreign` (`vehicle_uuid`),
  CONSTRAINT `procedures_city_uuid_foreign` FOREIGN KEY (`city_uuid`) REFERENCES `cities` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `procedures_company_uuid_foreign` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `procedures_territorial_director_uuid_foreign` FOREIGN KEY (`territorial_director_uuid`) REFERENCES `territorial_directors` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `procedures_third_party_uuid_foreign` FOREIGN KEY (`third_party_uuid`) REFERENCES `third_parties` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `procedures_vehicle_uuid_foreign` FOREIGN KEY (`vehicle_uuid`) REFERENCES `vehicles` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

