  KEY `fk_sheet_project` (`project_uuid`),
  KEY `idx_sdc_day_kind` (`day_kind`),
  KEY `idx_sdcs_company_date` (`company_uuid`,`service_date`),
  CONSTRAINT `fk_sheet_project` FOREIGN KEY (`project_uuid`) REFERENCES `projects` (`uuid`) ON DELETE SET NULL,
  CONSTRAINT `service_delivery_control_sheet_parent_uuid_foreign` FOREIGN KEY (`parent_uuid`) REFERENCES `service_delivery_control_sheet` (`uuid`) ON DELETE SET NULL
