--
-- Table structure for table `third_parties`
--

DROP TABLE IF EXISTS `third_parties`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `third_parties` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `company_uuid` char(36) NOT NULL,
  `person_type` enum('NATURAL','JURIDICA') NOT NULL,
  `document_type_uuid` char(36) NOT NULL,
  `document_number` varchar(20) NOT NULL,
  `nit_check_digit` char(1) DEFAULT NULL,
  `trade_name` varchar(200) DEFAULT NULL,
  `company_name` varchar(200) DEFAULT NULL,
  `first_name` varchar(100) DEFAULT NULL,
  `last_name` varchar(100) DEFAULT NULL,
  `email` varchar(100) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `address` varchar(200) DEFAULT NULL,
  `municipality_uuid` char(36) NOT NULL,
  `tax_regime` enum('48','49','47','05','42') NOT NULL,
  `tax_responsibility_uuid` char(36) NOT NULL,
  `bank_account_number` varchar(50) DEFAULT NULL,
  `bank_account_type` enum('AHORROS','CORRIENTE','MONEDA_EXTRANJERA') DEFAULT NULL,
  `bank_name` varchar(100) DEFAULT NULL,
  `cost_center_uuid` char(36) DEFAULT NULL,
  `is_customer` tinyint(1) NOT NULL DEFAULT 0,
  `is_supplier` tinyint(1) NOT NULL DEFAULT 0,
  `is_employee` tinyint(1) NOT NULL DEFAULT 0,
  `is_affiliate` tinyint(1) NOT NULL DEFAULT 0,
  `is_driver` tinyint(1) NOT NULL DEFAULT 0,
  `is_others` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_company_doc` (`company_uuid`,`document_type_uuid`,`document_number`),
  UNIQUE KEY `uk_uuid` (`uuid`),
  KEY `idx_municipality` (`municipality_uuid`),
  KEY `idx_tax_responsibility` (`tax_responsibility_uuid`),
  KEY `idx_cost_center` (`cost_center_uuid`),
  KEY `fk_tp_doc_type` (`document_type_uuid`),
  CONSTRAINT `fk_tp_company` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE,
  CONSTRAINT `fk_tp_doc_type` FOREIGN KEY (`document_type_uuid`) REFERENCES `type_of_documents` (`uuid`),
  CONSTRAINT `fk_tp_municipality` FOREIGN KEY (`municipality_uuid`) REFERENCES `cities` (`uuid`),
  CONSTRAINT `fk_tp_tax_resp` FOREIGN KEY (`tax_responsibility_uuid`) REFERENCES `tax_responsibilities` (`uuid`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

