DROP TABLE IF EXISTS `tributes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tributes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL COMMENT 'UUID V4 ÚNICO DEL TRIBUTO',
  `dian_code` varchar(10) NOT NULL COMMENT 'CÓDIGO DIAN DEL TRIBUTO (01:IVA, 04:INC, ZA:NO APLICA, ETC.)',
  `name` varchar(100) NOT NULL COMMENT 'NOMBRE OFICIAL DEL TRIBUTO SEGÚN DIAN',
  `description` varchar(255) DEFAULT NULL COMMENT 'DESCRIPCIÓN O ACLARACIÓN DEL TRIBUTO',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'ESTADO DE HABILITACIÓN',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tributes_uuid_unique` (`uuid`),
  UNIQUE KEY `tributes_dian_code_unique` (`dian_code`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

