CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador único autoincremental',
  `name` varchar(255) NOT NULL COMMENT 'Nombre del usuario',
  `uuid` char(36) NOT NULL COMMENT 'Identificador único universal',
  `email` varchar(255) NOT NULL COMMENT 'Correo electrónico único',
  `user_name` varchar(255) DEFAULT NULL COMMENT 'Nombre de usuario, puede ser único si aplica',
  `email_verified_at` timestamp NULL DEFAULT NULL COMMENT 'Fecha de verificación de correo',
  `password` varchar(255) NOT NULL COMMENT 'Contraseña',
  `verification_code` varchar(255) DEFAULT NULL COMMENT 'Código de verificación',
  `verification_code_expires_at` timestamp NULL DEFAULT NULL COMMENT 'Expiración del código de verificación',
  `last_login_at` timestamp NULL DEFAULT NULL COMMENT 'Último inicio de sesión',
  `failed_login_attempts` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'Intentos fallidos de inicio de sesión',
  `locked_until` timestamp NULL DEFAULT NULL COMMENT 'Fecha hasta la que el usuario está bloqueado',
  `google_id` varchar(255) DEFAULT NULL COMMENT 'Identificador único de Google',
  `google_email` varchar(255) DEFAULT NULL COMMENT 'Correo electrónico de Google',
  `google_drive_refresh_token` varchar(255) DEFAULT NULL COMMENT 'Token de actualización de Google Drive',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'Estado del usuario',
  `remember_token` varchar(100) DEFAULT NULL COMMENT 'Token para recordar sesión',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_uuid_unique` (`uuid`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
