--
-- Table structure for table `vehicle_inspections`
--

DROP TABLE IF EXISTS `vehicle_inspections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vehicle_inspections` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL COMMENT 'UUID único universal del resultado de la inspección',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID único universal de la empresa',
  `vehicle_uuid` char(36) NOT NULL COMMENT 'UUID único universal del vehículo',
  `inspection_date` date NOT NULL COMMENT 'Fecha de la inspección',
  `inspector_name` varchar(150) DEFAULT NULL COMMENT 'Nombre del inspector',
  `mileage` int(10) unsigned DEFAULT NULL COMMENT 'Kilometraje del vehículo',
  `driver_uuid` char(36) DEFAULT NULL COMMENT 'UUID único universal del conductor',
  `notes` text DEFAULT NULL COMMENT 'Notas adicionales',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vehicle_inspections_uuid_unique` (`uuid`),
  KEY `vehicle_inspections_vehicle_uuid_foreign` (`vehicle_uuid`),
  KEY `vehicle_inspections_company_uuid_foreign` (`company_uuid`),
  KEY `vehicle_inspections_driver_uuid_foreign` (`driver_uuid`),
