  CONSTRAINT `vehicle_inspections_vehicle_uuid_foreign` FOREIGN KEY (`vehicle_uuid`) REFERENCES `vehicles` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
