--
-- Table structure for table `vehicles`
--

DROP TABLE IF EXISTS `vehicles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vehicles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID único del vehículo',
  `uuid` char(36) NOT NULL COMMENT 'UUID único universal del vehículo',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID único universal de la empresa',
  `third_party_uuid` char(36) DEFAULT NULL COMMENT 'UUID único universal del tercero',
  `vehicle_license_plate` varchar(20) NOT NULL COMMENT 'Placa del vehículo',
  `transit_license_number` varchar(20) NOT NULL COMMENT 'Número de la licencia de tránsito',
  `type_of_service` enum('PUBLICO','PARTICULAR') NOT NULL DEFAULT 'PUBLICO' COMMENT 'Tipo de servicio del vehículo',
  `vehicle_class_uuid` char(36) NOT NULL COMMENT 'UUID único universal de la clase de vehículo',
  `brand_uuid` char(36) NOT NULL COMMENT 'UUID único universal de la marca',
  `line` varchar(50) NOT NULL COMMENT 'Línea del vehículo',
  `model` varchar(10) NOT NULL COMMENT 'Modelo del vehículo',
  `color` varchar(30) NOT NULL COMMENT 'Color del vehículo',
  `serial_number` varchar(50) DEFAULT NULL COMMENT 'Número de serie del vehículo',
  `engine_number` varchar(50) NOT NULL COMMENT 'Número de motor del vehículo',
  `chassis_number` varchar(50) NOT NULL COMMENT 'Número de chasis del vehículo',
  `vin_number` varchar(50) DEFAULT NULL COMMENT 'Número de VIN del vehículo',
  `engine_displacement` varchar(20) NOT NULL COMMENT 'Cilindraje del motor',
  `body_type` varchar(30) NOT NULL COMMENT 'Tipo de carrocería del vehículo',
  `fuel_type` enum('GASOLINA','DIESEL','GAS','ELECTRICIDAD','HIBRIDO','OTRO') NOT NULL COMMENT 'Tipo de combustible del vehículo',
  `registration_date` date NOT NULL COMMENT 'Fecha de registro del vehículo',
  `transit_authority` varchar(50) NOT NULL COMMENT 'Autoridad de tránsito del vehículo',
  `doors` int(11) NOT NULL COMMENT 'Número de puertas del vehículo',
  `load_capacity` int(11) NOT NULL COMMENT 'Capacidad de carga del vehículo',
  `gross_vehicle_weight` int(11) NOT NULL COMMENT 'Peso bruto vehicular',
  `passenger_capacity` int(11) NOT NULL COMMENT 'Capacidad de pasajeros del vehículo',
  `seated_passenger_capacity` int(11) NOT NULL COMMENT 'Capacidad de pasajeros sentados del vehículo',
  `number_of_axles` int(11) NOT NULL COMMENT 'Número de ejes del vehículo',
  `exact_payment` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Indica si el pago es exacto',
  `internal_number` varchar(20) DEFAULT NULL COMMENT 'Número interno del vehículo',
  `address_type` varchar(100) NOT NULL COMMENT 'Tipo de dirección',
  `steering_type` varchar(30) DEFAULT NULL COMMENT 'Tipo de dirección',
  `transmission_type` varchar(30) DEFAULT NULL COMMENT 'Tipo de transmisión',
  `number_of_speeds` varchar(30) DEFAULT NULL COMMENT 'Número de velocidades',
  `bearing_type` varchar(30) DEFAULT NULL COMMENT 'Tipo de rodamiento',
  `rear_suspension` varchar(30) DEFAULT NULL COMMENT 'Tipo de suspensión trasera',
  `number_of_tires` varchar(20) DEFAULT NULL COMMENT 'Número de llantas',
  `rim_size` varchar(20) DEFAULT NULL COMMENT 'Tamaño del rin',
  `rim_material` varchar(20) DEFAULT NULL COMMENT 'Material del rin',
  `front_brake_type` varchar(30) DEFAULT NULL COMMENT 'Tipo de freno delantero',
  `rear_brake_type` varchar(30) DEFAULT NULL COMMENT 'Tipo de freno trasero',
  `number_of_windows` varchar(20) DEFAULT NULL COMMENT 'Número de ventanas',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Indica si el vehículo está activo',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vehicles_uuid_unique` (`uuid`),
  KEY `vehicles_brand_uuid_foreign` (`brand_uuid`),
  KEY `vehicles_vehicle_class_uuid_foreign` (`vehicle_class_uuid`),
  KEY `vehicles_company_uuid_foreign` (`company_uuid`),
  KEY `vehicles_third_party_uuid_foreign` (`third_party_uuid`),
  CONSTRAINT `vehicles_brand_uuid_foreign` FOREIGN KEY (`brand_uuid`) REFERENCES `brands` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `vehicles_company_uuid_foreign` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `vehicles_third_party_uuid_foreign` FOREIGN KEY (`third_party_uuid`) REFERENCES `third_parties` (`uuid`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `vehicles_vehicle_class_uuid_foreign` FOREIGN KEY (`vehicle_class_uuid`) REFERENCES `vehicle_class` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=116 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

