DROP TABLE IF EXISTS `withholdings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `withholdings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL COMMENT 'UUID V4 ÚNICO DE LA RETENCIÓN',
  `code` varchar(20) NOT NULL COMMENT 'CÓDIGO INTERNO DE LA RETENCIÓN',
  `name` varchar(150) NOT NULL COMMENT 'DENOMINACIÓN OFICIAL DE LA RETENCIÓN',
  `type` enum('RETEFUENTE','RETEIVA','RETEICA','RETECREE','AUTORETENCIÓN') NOT NULL COMMENT 'TIPO DE RETENCIÓN SEGÚN CLASIFICACIÓN TRIBUTARIA',
  `dian_concept` varchar(10) DEFAULT NULL COMMENT 'CONCEPTO DIAN APLICABLE',
  `base_minimum` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT 'BASE MÍNIMA EN COP PARA APLICAR LA RETENCIÓN',
  `rate` decimal(8,6) NOT NULL COMMENT 'PORCENTAJE DE RETENCIÓN (EJ: 0.035000 = 3.5%)',
  `debit_account` varchar(20) DEFAULT NULL COMMENT 'CUENTA CONTABLE DE DÉBITO PARA LA RETENCIÓN',
  `credit_account` varchar(20) DEFAULT NULL COMMENT 'CUENTA CONTABLE DE CRÉDITO PARA LA RETENCIÓN',
  `applies_purchases` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'INDICA SI SE RETIENE A PROVEEDORES EN COMPRAS',
  `applies_sales` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'INDICA SI SE RETIENE A CLIENTES EN VENTAS',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'INDICA SI LA CONFIGURACIÓN DE RETENCIÓN ESTÁ ACTIVA',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `withholdings_uuid_unique` (`uuid`),
  UNIQUE KEY `withholdings_code_unique` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

